/* AFL file-input target: sslh's configuration-file reader, run as `sslh -F <file>` reads it.
 * sslhcfg_cl_parse() (sslh-conf.c, generated by conf2struct) parses the file with libconfig and
 * walks the tree into struct sslhcfg_item (listen/protocols lists, sni_hostnames/alpn_protocols/
 * regex_patterns arrays, defaults, type checks); sslhcfg_fprint() then prints the result, as
 * verbose-config does at startup.
 *
 * Why a one-input-per-process AFL target and not libFuzzer: sslhcfg_cl_parse() never destroys its
 * libconfig tree and the parsed strings are never freed (sslh parses its config once per
 * process), so an in-process loop grows ~20 KB per input and hits libFuzzer's 2 GB RSS limit in
 * about a minute. Here every input gets a fresh process. */
#include <stdio.h>
#include <string.h>
#include "sslh-conf.h"

int main(int argc, char **argv)
{
    struct sslhcfg_item c;
    if (argc != 2) { fprintf(stderr, "usage: %s <config file>\n", argv[0]); return 2; }
    char *av[] = { (char *)"sslh", (char *)"-F", argv[1], NULL };
    memset(&c, 0, sizeof(c));
    if (sslhcfg_cl_parse(3, av, &c) != 0) return 1;
    FILE *devnull = fopen("/dev/null", "w");
    sslhcfg_fprint(devnull ? devnull : stdout, &c, 0);
    return 0;
}
